S=dict(slice={}, cust={})
def keep(sub,v,m,read): add(sub,v,m,1,read=read)
def drop(sub,v,m,note): add(sub,v,m,1,verdict="drop",note=note)
# ---- slice
keep('slice','A','klein',"The safe baseline. Reads as the current character with a hard black ground shadow; barely grotesque, barely noir. Works at 124 px, but it is not the direction Tommy asked for.")
keep('slice','B','klein',"Droopy limbs, crooked yellow teeth and a veiny eye survive at 124 px as a face that is clearly 'wrong'. The shadow went onto the backdrop and the floor, not onto the figure, so it is grotesque with almost no noir.")
keep('slice','C','klein',"Same as B, a little muddier. Klein ignores 'shadow blocks on the body' and only lights the figure flat. Noir comes out as a floor shadow.")
keep('slice','D','klein',"Style ref Real Monsters pushes the cheese to a sickly pale yellow with a lumpy face, and this one holds together. Colour is a step off the game's cheese gold (#f5b82a): fixable in the palette stage. Good at 2x, a little flat at 1x.")
keep('slice','E','klein',"Similar to D, with a slightly heavier brow and hatching. Shadow is still on the floor. Safe but not bold.")
keep('slice','F','klein',"Most grotesque of the Klein set, the face is a mess in a good way. The lower arms lost their gloves (cream stumps): a pipeline reject unless fixed.")
keep('slice','A','qwen-edit',"Qwen already pushes the grin and the red eyes further than Klein on the safest settings. Keeps the pixel-painted look of the master, so it sits in the current game most easily.")
keep('slice','B','qwen-edit',"Fanged grin, bulging red-veined eyes, soft cast shadow behind. Grotesque and still clearly Vinny. One of the best at 124 px because the face has big, high-contrast shapes.")
keep('slice','C','qwen-edit',"The closest to what was asked: a solid violet-black block falls across the crust and brow, the lit face stays readable (one eye, fanged grin), and it holds at 124 px and in the street frame. Risk: the block took one eye on this seed, and it is luck rather than control, so it will not repeat on demand.")
keep('slice','D','qwen-edit',"The Real Monsters style ref gives a drooling tongue, ruffled crust, thin noodle limbs: the best grotesque. It reads at 1x because the tongue and teeth are large flat shapes. Shadow is still a floor shadow, no blocks on the body.")
keep('slice','E','qwen-edit',"D with a purple backdrop and more hatching on the cheese; the face is the strongest of the set, with big veiny eyes, a spiralling tongue and a hard shadow on the ground. Halftone is invisible at 124 px.")
keep('slice','F','qwen-edit',"Most extreme: gloves on the wrong side, wobbly arms. At game size the dots disappear and the cheese becomes noise. Overshoots on faces for a hero.")
# ---- customer
keep('cust','A','klein',"Close to the current art, with a harder jaw. Safe baseline. Reads at 130 px but is plain.")
keep('cust','B','klein',"Veiny red eyes, flying sweat, big yelling mouth. The expression survives down to 130 px. Shadow is a cast shape on the backdrop behind her, not on her.")
keep('cust','C','klein',"Wider eyes, more teeth. Reads as 'screaming' at 2x. The pinstripes fall to noise at 1x.")
drop('cust','D','klein',"extra dangling arm at her right hip on both seeds")
keep('cust','E','klein',"Strongest face of the Klein set: the whites of the eyes and the teeth stay readable. The ink-black outline is already thick. Shadow on the figure is a soft darkening, not a hard block.")
keep('cust','F','klein',"E with yellow hair highlights and heavier lines. About the same, a little more noisy.")
keep('cust','A','qwen-edit',"Pixel-painted, close to the current customer. A black floor shadow reaches left, which has to be cropped before it ships.")
keep('cust','B','qwen-edit',"Magenta gap between the legs leaks after keying (cleaned here). Face reads, but the pinstripe becomes dotted noise at 130 px.")
keep('cust','C','qwen-edit',"Yellow face, bulging eyes, very grotesque; the face has the wrong skin tone for a pipeline that wants a stable palette.")
drop('cust','D','qwen-edit',"spotlight cone in the backdrop merges with the figure when keyed, on both seeds")
keep('cust','E','qwen-edit',"Bloodshot eyes with veins, spit, a huge scream. The most character of the set, but pinstripes plus eye detail are very busy at 130 px.")
keep('cust','F','qwen-edit',"E with more spit; the same strengths and noise.")
NR={1:'A shadow on the far side of the figure as one flat violet-black block with a hard edge. The face stays lit and readable at 124/130 px. This is the safest way to get Tommy\'s hard shadow: it is a post pass, so every character in the cast would get the same one.',2:'Harder and larger block with a 2 px dot dither along the edge. The dots survive only as a texture at 2x. The shadow now takes a bite of the face, so the light angle would need to be set per character.',3:'The bold one: half the figure goes to violet-black and the terminator is a halftone band. It is striking in the street frame, but it eats the second eye and the sneaker on the shadow side. Too much for a hero, plausible for a customer in a doorway.'}
# ---- code-added hard shadow variants (post pass on the cleanest grotesque bases)
for lvl,lab,ax in [(1,"N1: code shadow, soft terminator","grotesque from base / shadow 1 added in code / halftone 0"),(2,"N2: code shadow, hard terminator + dots","grotesque from base / shadow 2 added in code / halftone 1"),(3,"N3: code shadow, half the figure + halftone band","grotesque from base / shadow 3 added in code / halftone 3")]:
    for sub,base,m in [('slice','slice_D','qwen-edit'),('cust','cust_E','klein')]:
        R[f"{sub}_N{lvl}/{m}/1"]=dict(verdict="keep",label=lab,axes=ax+f" (base {base} {m} seed 1)",base=base,noir=lvl,read=NR[lvl])
